@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_container" style="display:contents">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }
    [Parameter] public int TimeoutSeconds { get; set; } = 300;
    [Parameter] public EventCallback OnIdle { get; set; }
    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _container;
    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;
    private System.Timers.Timer? _timer;
    private bool _isIdle;
    private bool _disposed;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        _dotNetRef = DotNetObjectReference.Create(this);
        _jsModule = await JS.InvokeAsync<IJSObjectReference>(
            "import", "./_content/sv-1f7a4f0ccbff414d8ba1809c5b2f0dae/Components/UserActivityTracker.razor.js");

        await _jsModule.InvokeVoidAsync("init", _container, _dotNetRef);

        _timer = new System.Timers.Timer(TimeoutSeconds * 1000);
        _timer.AutoReset = false;
        _timer.Elapsed += OnTimerElapsed;
        _timer.Start();
    }

    [JSInvokable]
    public async Task OnUserActivity()
    {
        if (_disposed) return;

        // Reset the inactivity timer
        _timer?.Stop();
        _timer?.Start();

        if (_isIdle)
        {
            _isIdle = false;
            await OnActive.InvokeAsync();
        }
    }

    private async void OnTimerElapsed(object? sender, System.Timers.ElapsedEventArgs e)
    {
        if (_disposed) return;

        _isIdle = true;
        await InvokeAsync(async () => await OnIdle.InvokeAsync());
    }

    public async ValueTask DisposeAsync()
    {
        if (_disposed) return;
        _disposed = true;

        if (_timer is not null)
        {
            _timer.Elapsed -= OnTimerElapsed;
            _timer.Stop();
            _timer.Dispose();
        }

        if (_jsModule is not null)
        {
            try
            {
                await _jsModule.InvokeVoidAsync("dispose");
                await _jsModule.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }

        _dotNetRef?.Dispose();
    }
}

let handler = null;
let element = null;

export function init(el, dotNetRef) {
    element = el;

    handler = () => {
        dotNetRef.invokeMethodAsync('OnUserActivity');
    };

    element.addEventListener('mousemove', handler, { passive: true });
    element.addEventListener('keydown', handler, { passive: true });
    element.addEventListener('click', handler, { passive: true });
    element.addEventListener('scroll', handler, { passive: true, capture: true });
}

export function dispose() {
    if (element && handler) {
        element.removeEventListener('mousemove', handler);
        element.removeEventListener('keydown', handler);
        element.removeEventListener('click', handler);
        element.removeEventListener('scroll', handler, { capture: true });
    }
    handler = null;
    element = null;
}

